const body = $input.first().json.body;
const issue = body.data || body;

const title = (issue.title || issue.data?.title || 'Neues Linear-Ticket').trim();
const description = issue.description || issue.data?.description || '';
const priority = issue.priority ?? issue.data?.priority ?? 0;
const labels = (issue.labels || issue.data?.labels || []).map(l => (l.name || '').toLowerCase());
const issueId = issue.id || issue.data?.id || '';
const identifier = issue.identifier || issue.data?.identifier || '';
const titleLower = title.toLowerCase();

let scope = 'standard';
if (labels.some(l => ['bug', 'hotfix', 'quick-fix', 'fix'].includes(l))) {
  scope = 'quick';
} else if (labels.some(l => ['epic', 'research', 'architecture', 'spike', 'deep'].includes(l))) {
  scope = 'deep';
} else if (priority <= 1) {
  scope = 'deep';
} else if (priority >= 3) {
  scope = 'quick';
}
if (titleLower.includes('[deep]') || titleLower.includes('spike') || titleLower.includes('architektur')) scope = 'deep';
if (titleLower.includes('[quick]') || titleLower.includes('[fix]')) scope = 'quick';

return [{
  json: {
    title,
    rawIdea: description || title,
    problemStatement: description,
    targetAudience: 'ForgePilot-Nutzer',
    desiredOutcome: `Issue '${title}' vollständig umsetzen`,
    scope,
    privacyMode: 'local',
    source: 'linear-webhook',
    linearIssueId: issueId,
    linearIdentifier: identifier,
    _issueId: issueId
  }
}];

const issueId = $('Linear → Intake Format').first().json._issueId;
const briefId = $('POST /api/intake').first().json.id || '';
const scope = $('Linear → Intake Format').first().json.scope;
const scopeEmoji = scope === 'deep' ? '🔬' : scope === 'quick' ? '⚡' : '📋';
const body = `✅ **In ForgePilot verarbeitet** — KI-Research läuft...\n\n${scopeEmoji} Scope: **${scope}**\n\n→ http://100.94.55.15:3002/project-briefs/${briefId}`;
const query = `mutation { commentCreate(input: { issueId: "${issueId}", body: "${body.replace(/"/g, '\\"').replace(/\n/g, '\\n')}" }) { success } }`;
return [{ json: { query, issueId, briefId } }];

const issueId = $('Linear → Intake Format').first().json._issueId;
const response = $('POST /api/intake').first().json;
const errorMsg = response.error || response.message || JSON.stringify(response).slice(0, 200);
const body = `⚠️ **ForgePilot-Fehler**

Das Ticket konnte nicht als Brief angelegt werden:
\`${errorMsg}\`

→ Manuell anlegen: http://100.94.55.15:3002/project-briefs/new`;
const query = `mutation { commentCreate(input: { issueId: "${issueId}", body: "${body.replace(/"/g, '\"').replace(/
/g, '\n')}" }) { success } }`;
return [{ json: { query, issueId } }];

const issueId = $('Linear → Intake Format').first().json._issueId;
const briefId = $('Kommentar (Erfolg)').first().json.briefId;
const research = $input.first().json;

if (!research || research.error) {
  return [{ json: { skip: true } }];
}

const score = research.confidenceScore ?? research.lastResearchRun?.confidenceScore ?? 0;
const summary = research.summary || research.lastResearchRun?.summary || 'Research abgeschlossen.';
const findings = (research.findings || research.lastResearchRun?.findings || []).slice(0, 3);
const uncertainties = (research.openUncertainties || research.lastResearchRun?.openUncertainties || []).slice(0, 2);
const newReqs = (research.requirements || []).filter(r => r.source === 'research').length;
const cost = research.actualCostUsd || research.lastResearchRun?.actualCostUsd || 0;

const confEmoji = c => c === 'high' ? '🟢' : c === 'medium' ? '🟡' : '🔴';

const findingsText = findings.length > 0
  ? findings.map(f => `• ${confEmoji(f.confidence)} ${f.claim.slice(0, 100)}`).join('\n')
  : '• Keine spezifischen Findings';

const uncertaintiesText = uncertainties.length > 0
  ? uncertainties.map(u => `• ⚠️ ${u.slice(0, 80)}`).join('\n')
  : '';

let body = `🔬 **KI-Research abgeschlossen**\n\n📊 Konfidenz: **${score}%** | 💰 Kosten: $${cost.toFixed(4)}\n\n${summary.slice(0, 200)}\n\n**Top Findings:**\n${findingsText}`;
if (uncertaintiesText) body += `\n\n**Offene Annahmen:**\n${uncertaintiesText}`;
if (newReqs > 0) body += `\n\n✅ **${newReqs} neue Requirements** in ForgePilot eingetragen`;
body += `\n\n→ http://100.94.55.15:3002/project-briefs/${briefId}`;

const query = `mutation { commentCreate(input: { issueId: "${issueId}", body: "${body.replace(/"/g, '\\"').replace(/\n/g, '\\n')}" }) { success } }`;
return [{ json: { query, skip: false } }];
